#pragma inline_depth()
        if (!p)
            p = &m_players.m_computerPlayers[msg->m_gamePos];
        if (p) {
            p->m_startBonusIndex = msg->m_agr;
            drawHeroAdvancedOption(msg->m_gamePos, 1, -1);
        }
        break;
